@@ -0,0 +1,14 @@
+import { AppError } from "../errors.js";
+
+/** Creates a request-local store context without changing the shared store. */
+export function forSite(store, site = "main") {
+  if (!store.data.sites.some((s) => s.id === site)) throw new AppError("unknown_site", { id: site });
+  const context = Object.create(store);
+  context.site = site;
+  return context;
+}
+
+/** Whether a location belongs to the context's site (main outside requests). */
+export function locationInSite(store, location) {
+  return store.data.locations.some((l) => l.id === location && l.site === (store.site ?? "main"));
+}
