diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..b26f8e2
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,74 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+function kitchens() {
+  const context = app();
+  const batch = { ...context.store.data.batches[0], id: context.store.nextId("batch"), location: "annex-fridge", qty: 100 };
+  context.store.data.batches.push(batch);
+  return { ...context, batch };
+}
+
+test("site selection defaults to main, accepts mixed-case headers and rejects unknown sites", async () => {
+  const { handle } = kitchens();
+  const main = await handle({ path: "/items/1" });
+  assert.equal(main.body.onHand, 10);
+  const other = await handle({ path: "/items/1", headers: { "x-LaRdEr-SiTe": "annex" } });
+  assert.equal(other.body.onHand, 100);
+  assert.equal(main.body.name, other.body.name);
+  for (const site of ["missing", ""]) {
+    const res = await handle({ path: "/items", headers: { "X-Larder-Site": site } });
+    assert.equal(res.status, 400);
+    assert.equal(res.body.error.code, "unknown_site");
+    assert.match(res.body.error.message, /There is no site/);
+  }
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+});
+
+test("batches, waste, alerts and stock value are isolated by location site", async () => {
+  const { handle, store, batch } = kitchens();
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  const before = structuredClone(store.data);
+  const waste = await handle({ method: "POST", path: `/batches/${batch.id}/waste`, body: { qty: 1 } });
+  assert.equal(waste.body.error.code, "unknown_batch");
+  assert.deepEqual(store.data, before);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.ok(alerts.expiring.every((b) => b.id === batch.id));
+  assert.ok(alerts.lowStock.some((i) => i.itemId === 2 && i.qty === 0));
+  assert.ok(!alerts.lowStock.some((i) => i.itemId === 1));
+  const value = (await handle({ path: "/reports/stock-value", headers: annex })).body;
+  assert.equal(value.totalCents, 100 * store.data.items[0].priceCents);
+  assert.equal(value.lines.find((l) => l.itemId === 1).qty, 100);
+  assert.equal((await handle({ method: "POST", path: `/batches/${batch.id}/waste`, headers: annex, body: { qty: 1 } })).status, 201);
+  assert.equal(batch.qty, 99);
+});
+
+test("cooking cannot borrow another site's ingredients and leaves stock unchanged on failure", async () => {
+  const { handle, store } = kitchens();
+  const before = structuredClone(store.data);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.deepEqual(store.data, before);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 4 } })).status, 200);
+  assert.equal(store.data.batches.at(-1).qty, 100);
+});
+
+test("stock-takes cannot start, count or finish across sites", async () => {
+  const { handle, store, batch } = kitchens();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  const before = structuredClone(store.data);
+  for (const [suffix, body] of [["counts", { batchId: batch.id, counted: 5 }], ["finish", null]]) {
+    assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/${suffix}`, body })).status, 404);
+  }
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: 1, counted: 5 } })).status, 404);
+  assert.deepEqual(store.data, before);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: batch.id, counted: 5 } });
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 200);
+  assert.equal(batch.qty, 5);
+  assert.equal(store.data.movements.at(-1).batchId, batch.id);
+});
